273	  // sanity check
274	  // check if all invert conds exist in one sub-tree, if yes,
275	  // move the sub-tree as final invert cond for query.
276	  if (invert_size > 0) {
277	    QueryNode *invert_subroot =
278	        get_invert_subroot(query_info->search_cond().get());
