187	        "FtsColumnIndexer::search: must_not on root is not allowed. field[%s]",
188	        field_name_.c_str());
189	    return tl::make_unexpected(Status::InvalidArgument(
190	        "FtsColumnIndexer::search: must_not on root is not allowed. field=",
191	        field_name_));
192	  }
193	
194	  auto iter_result = build_iterator(ast);
195	  if (!iter_result.has_value()) {
196	    LOG_ERROR("FtsColumnIndexer::search: build_iterator failed. field[%s] %s",
197	              field_name_.c_str(), iter_result.error().message().c_str());
198	    return tl::make_unexpected(iter_result.error());
199	  }
200	  DocIteratorPtr root_iter = std::move(iter_result.value());
201	  if (!root_iter) {
202	    // No matching terms found — valid empty result, not an error.
203	    return std::vector<FtsResult>{};
204	  }
205	
206	  // Candidate-driven mode: AND a CandidateDocIterator into the root so the
207	  // small candidate set leads (Conjunction sorts by cost asc), turning the
208	  // posting walk into per-candidate advance()+matches()+score().
209	  if (!query_params.candidate_ids.empty()) {
210	    std::vector<DocIteratorPtr> musts;
211	    musts.reserve(2);
212	    musts.push_back(
213	        std::make_unique<CandidateDocIterator>(query_params.candidate_ids));
214	    musts.push_back(std::move(root_iter));
215	    root_iter = std::make_unique<ConjunctionIterator>(
216	        std::move(musts), std::vector<DocIteratorPtr>{});
217	  }
218	
219	  const uint32_t topk = query_params.topk;
220	  const zvec::IndexFilter *filter_ptr = query_params.filter.get();
221	
222	  using MinHeap = std::priority_queue<FtsResult, std::vector<FtsResult>,
223	                                      std::greater<FtsResult>>;
224	  MinHeap min_heap;
225	
226	  // Filter pushdown: when a filter is present, use the filter-aware next_doc
227	  // overload so composite iterators skip filtered docs before paying for
228	  // block-max binary search, do_next alignment, or phase-2 position checks.
229	  uint32_t doc_id =
230	      filter_ptr ? root_iter->next_doc(filter_ptr) : root_iter->next_doc();
231	  while (doc_id != DocIterator::NO_MORE_DOCS) {
232	    const uint64_t global_doc_id = static_cast<uint64_t>(doc_id);
233	
234	    if (root_iter->matches()) {
235	      float s = root_iter->score();
236	      if (s > 0.0f) {
237	        if (min_heap.size() < topk) {
238	          min_heap.push({global_doc_id, s});
239	          if (min_heap.size() == topk) {
240	            root_iter->set_min_competitive_score(min_heap.top().score);
241	          }
242	        } else if (s > min_heap.top().score) {
243	          min_heap.pop();
244	          min_heap.push({global_doc_id, s});
245	          root_iter->set_min_competitive_score(min_heap.top().score);
246	        }
247	      }
248	    }
249	    doc_id =
250	        filter_ptr ? root_iter->next_doc(filter_ptr) : root_iter->next_doc();
251	  }
252	
253	  std::vector<FtsResult> results(min_heap.size());
254	  for (auto it = results.rbegin(); it != results.rend(); ++it) {
255	    *it = min_heap.top();
256	    min_heap.pop();
257	  }
258	
259	  return results;
260	}
