38	Result<InvertedSearchResult::Ptr> InvertSearch::exec_invert_cond_tree(
39	    const QueryNode *query_node) {
40	  if (query_node->type() == QueryNode::QueryNodeType::LOGIC_EXPR) {
41	    if (query_node->left() != nullptr) {
42	      auto left_res = exec_invert_cond_tree(query_node->left_node());
43	      if (!left_res) {
44	        return left_res;
45	      }
46	      if (query_node->right() == nullptr) {
47	        return left_res;
48	      } else {
49	        auto right_res = exec_invert_cond_tree(query_node->right_node());
50	        if (!right_res) {
51	          return right_res;
52	        }
53	        query_node->op() == QueryNodeOp::Q_AND
54	            ? left_res.value()->AND(*right_res.value())
55	            : left_res.value()->OR(*right_res.value());
56	        return left_res;
57	      }
58	    }
59	    if (query_node->right() != nullptr) {
60	      return exec_invert_cond_tree(query_node->right_node());
61	    }
62	    return tl::make_unexpected(Status::InvalidArgument(
63	        "exec_invert_cond_tree, logic expr has no left or right node."));
64	  }
65	
66	  if (query_node->type() == QueryNode::QueryNodeType::REL_EXPR) {
67	    return exec_invert_cond_node(query_node);
68	  }
69	
70	  return tl::make_unexpected(Status::InvalidArgument(
71	      "exec_invert_cond_tree unexpected type:", query_node->op_name()));
72	}
